model.view:
{
  "version": 1,
  "state": [
    {
      "id": "idle",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"idle\""
        ]
      },
      "label": "Ready"
    },
    {
      "id": "starting",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"starting\""
        ]
      },
      "label": "Starting"
    },
    {
      "id": "polling",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"polling\""
        ]
      },
      "label": "Generating"
    },
    {
      "id": "saved",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"done\""
        ]
      },
      "label": "Delivered"
    },
    {
      "id": "error",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"error\""
        ]
      },
      "label": "Error; can start again"
    },
    {
      "id": "delivery",
      "when": true,
      "label": "Downloading or delivering"
    }
  ],
  "step": [
    {
      "id": "reload",
      "when": {
        "not": {
          "eq": [
            {
              "from": "mount"
            },
            {
              "to": "mount"
            }
          ]
        }
      },
      "label": "Reload"
    },
    {
      "id": "error",
      "when": {
        "all": [
          {
            "not": {
              "eq": [
                {
                  "from": "phase"
                },
                "\"error\""
              ]
            }
          },
          {
            "eq": [
              {
                "to": "phase"
              },
              "\"error\""
            ]
          }
        ]
      },
      "label": "Report error and release guard"
    },
    {
      "id": "start",
      "when": {
        "all": [
          {
            "not": {
              "eq": [
                {
                  "from": "phase"
                },
                "\"starting\""
              ]
            }
          },
          {
            "eq": [
              {
                "to": "phase"
              },
              "\"starting\""
            ]
          }
        ]
      },
      "label": "Accept start"
    },
    {
      "id": "clear",
      "when": {
        "eq": [
          {
            "action": true
          },
          "Clear"
        ]
      },
      "label": "Clear"
    },
    {
      "id": "recover",
      "when": {
        "eq": [
          {
            "action": true
          },
          "Recover"
        ]
      },
      "label": "Recover latest task"
    },
    {
      "id": "deliver",
      "when": {
        "all": [
          {
            "not": {
              "eq": [
                {
                  "from": "phase"
                },
                "\"done\""
              ]
            }
          },
          {
            "eq": [
              {
                "to": "phase"
              },
              "\"done\""
            ]
          }
        ]
      },
      "label": "Delivery completes"
    },
    {
      "id": "other",
      "when": true,
      "label": "Task, poll, or callback step"
    }
  ]
}

